import { User } from './types';
import { randomUUID } from 'crypto';

export class UserService {
    private users: Map<string, User> = new Map();

    createUser(name: string, email: string): User {
        const id = randomUUID();
        const user: User = { id, name, email };
        this.users.set(id, user);
        return user;
    }

    getUser(id: string): User | undefined {
        return this.users.get(id);
    }

    getUsers(): User[] {
        return Array.from(this.users.values());
    }

    updateUser(id: string, name?: string, email?: string): User | undefined {
        const user = this.users.get(id);
        if (!user) {
            return undefined;
        }

        if (name) {
            user.name = name;
        }
        if (email) {
            user.email = email;
        }
        return user;
    }

    deleteUser(id: string): boolean {
        return this.users.delete(id);
    }
}

import { Project } from './types';
import { randomUUID } from 'crypto';

export class ProjectService {
    private projects: Map<string, Project> = new Map();

    createProject(name: string, description: string): Project {
        const id = randomUUID();
        const project: Project = { id, name, description, memberIds: [] };
        this.projects.set(id, project);
        return project;
    }

    getProject(id: string): Project | undefined {
        return this.projects.get(id);
    }

    getProjects(): Project[] {
        return Array.from(this.projects.values());
    }

    updateProject(id: string, name?: string, description?: string): Project | undefined {
        const project = this.projects.get(id);
        if (!project) {
            return undefined;
        }

        if (name) {
            project.name = name;
        }
        if (description) {
            project.description = description;
        }
        return project;
    }

    deleteProject(id: string): boolean {
        return this.projects.delete(id);
    }

    addMemberToProject(projectId: string, userId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }
        return project;
    }

    removeMemberFromProject(projectId: string, userId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        project.memberIds = project.memberIds.filter(id => id !== userId);
        return project;
    }
}

import { Task, TaskStatus } from './types';
import { randomUUID } from 'crypto';
import { eventBus } from './event-bus';

export class TaskService {
    private tasks: Map<string, Task> = new Map();

    createTask(projectId: string, title: string, description: string): Task {
        const id = randomUUID();
        const task: Task = { id, projectId, title, description, status: 'todo' };
        this.tasks.set(id, task);
        return task;
    }

    getTask(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    getTasksByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    updateTask(id: string, title?: string, description?: string): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        if (title) {
            task.title = title;
        }
        if (description) {
            task.description = description;
        }
        return task;
    }

    deleteTask(id: string): boolean {
        const task = this.getTask(id);
        if(!task) return false;

        this.tasks.delete(id);
        return true;
    }

    assignTask(id: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        task.assigneeId = assigneeId;
        eventBus.publish('task.assigned', { taskId: id, assigneeId });
        return task;
    }

    updateTaskStatus(id: string, status: TaskStatus): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        // Validate status transition
        const validTransitions: { [key in TaskStatus]?: TaskStatus[] } = {
            'todo': ['in-progress'],
            'in-progress': ['done'],
        };

        if (validTransitions[task.status]?.includes(status)) {
            task.status = status;
            eventBus.publish('task.statusChanged', { taskId: id, status, assigneeId: task.assigneeId });
            return task;
        }

        return undefined; // Invalid transition
    }
}

import { Comment } from './types';
import { randomUUID } from 'crypto';
import { eventBus } from './event-bus';

export class CommentService {
    private comments: Map<string, Comment> = new Map();

    addComment(taskId: string, authorId: string, text: string): Comment {
        const id = randomUUID();
        const createdAt = new Date();
        const comment: Comment = { id, taskId, authorId, text, createdAt };
        this.comments.set(id, comment);

        eventBus.publish('comment.added', { taskId, authorId, text });

        return comment;
    }

    getComment(id: string): Comment | undefined {
        return this.comments.get(id);
    }

    getCommentsByTask(taskId: string): Comment[] {
        return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
    }

    deleteComment(id: string): boolean {
        return this.comments.delete(id);
    }
}

import { Notification } from './types';
import { randomUUID } from 'crypto';
import { eventBus } from './event-bus';
import { TaskService } from './task-service';

export class NotificationService {
    private notifications: Map<string, Notification> = new Map();

    constructor(private taskService: TaskService) { }

    setupSubscriptions() {
        eventBus.subscribe('task.assigned', (payload) => {
            const { taskId, assigneeId } = payload;
            const task = this.taskService.getTask(taskId);
            if (task && assigneeId) {
                const message = `You have been assigned to task: "${task.title}"`;
                this.createNotification(assigneeId, message);
            }
        });

        eventBus.subscribe('task.statusChanged', (payload) => {
            const { taskId, status, assigneeId } = payload;
            const task = this.taskService.getTask(taskId);
            if (task && assigneeId) {
                const message = `Task "${task.title}" status changed to "${status}"`;
                this.createNotification(assigneeId, message);
            }
        });

        eventBus.subscribe('comment.added', (payload) => {
            const { taskId, authorId, text } = payload;
            const task = this.taskService.getTask(taskId);
            if (task && task.assigneeId && task.assigneeId !== authorId) {
                const message = `New comment on task "${task.title}": "${text}"`;
                this.createNotification(task.assigneeId, message);
            }
        });
    }

    private createNotification(userId: string, message: string): Notification {
        const id = randomUUID();
        const createdAt = new Date();
        const notification: Notification = { id, userId, message, read: false, createdAt };
        this.notifications.set(id, notification);
        return notification;
    }

    getNotificationsForUser(userId: string): Notification[] {
        return Array.from(this.notifications.values()).filter(n => n.userId === userId && !n.read);
    }

    markAsRead(notificationId: string): Notification | undefined {
        const notification = this.notifications.get(notificationId);
        if (notification) {
            notification.read = true;
        }
        return notification;
    }
}

import * as http from 'http';
import { URL } from 'url';
import { UserService } from './user-service';
import { ProjectService } from './project-service';
import { TaskService } from './task-service';
import { CommentService } from './comment-service';
import { NotificationService } from './notification-service';

export class ApiRouter {
    constructor(
        private userService: UserService,
        private projectService: ProjectService,
        private taskService: TaskService,
        private commentService: CommentService,
        private notificationService: NotificationService
    ) { }

    handleRequest(req: http.IncomingMessage, res: http.ServerResponse) {
        const { method, url } = req;
        const { pathname, searchParams } = new URL(url || '', `http://${req.headers.host}`);

        res.setHeader('Content-Type', 'application/json');

        let body = '';
        req.on('data', chunk => { body += chunk; });
        req.on('end', async () => {
            try {
                const requestBody = body ? JSON.parse(body) : {};

                // User routes
                if (pathname === '/users' && method === 'GET') {
                    const users = this.userService.getUsers();
                    res.writeHead(200).end(JSON.stringify(users));
                } else if (pathname === '/users' && method === 'POST') {
                    const { name, email } = requestBody;
                    const user = this.userService.createUser(name, email);
                    res.writeHead(201).end(JSON.stringify(user));
                } else if (pathname.startsWith('/users/') && method === 'GET') {
                    const id = pathname.split('/')[2];
                    const user = this.userService.getUser(id);
                    if (user) {
                        res.writeHead(200).end(JSON.stringify(user));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'User not found' }));
                    }
                } else if (pathname.startsWith('/users/') && method === 'PUT') {
                    const id = pathname.split('/')[2];
                    const { name, email } = requestBody;
                    const user = this.userService.updateUser(id, name, email);
                    if (user) {
                        res.writeHead(200).end(JSON.stringify(user));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'User not found' }));
                    }
                } else if (pathname.startsWith('/users/') && method === 'DELETE') {
                    const id = pathname.split('/')[2];
                    const success = this.userService.deleteUser(id);
                    if (success) {
                        res.writeHead(204).end();
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'User not found' }));
                    }
                }

                // Project routes
                else if (pathname === '/projects' && method === 'GET') {
                    const projects = this.projectService.getProjects();
                    res.writeHead(200).end(JSON.stringify(projects));
                } else if (pathname === '/projects' && method === 'POST') {
                    const { name, description } = requestBody;
                    const project = this.projectService.createProject(name, description);
                    res.writeHead(201).end(JSON.stringify(project));
                } else if (pathname.startsWith('/projects/') && method === 'GET') {
                    const id = pathname.split('/')[2];
                    const project = this.projectService.getProject(id);
                    if (project) {
                        res.writeHead(200).end(JSON.stringify(project));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Project not found' }));
                    }
                } else if (pathname.startsWith('/projects/') && pathname.endsWith('/members') && method === 'POST') {
                    const projectId = pathname.split('/')[2];
                    const { userId } = requestBody;
                    const project = this.projectService.addMemberToProject(projectId, userId);
                    if (project) {
                        res.writeHead(200).end(JSON.stringify(project));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Project not found' }));
                    }
                } else if (pathname.startsWith('/projects/') && pathname.endsWith('/members') && method === 'DELETE') {
                    const projectId = pathname.split('/')[2];
                    const { userId } = requestBody;
                    const project = this.projectService.removeMemberFromProject(projectId, userId);
                    if (project) {
                        res.writeHead(200).end(JSON.stringify(project));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Project not found' }));
                    }
                }

                // Task routes
                else if (pathname === '/tasks' && method === 'GET') {
                    const projectId = searchParams.get('projectId');
                    if (projectId) {
                        const tasks = this.taskService.getTasksByProject(projectId);
                        res.writeHead(200).end(JSON.stringify(tasks));
                    } else {
                        res.writeHead(400).end(JSON.stringify({ message: 'Missing projectId query parameter' }));
                    }
                } else if (pathname === '/tasks' && method === 'POST') {
                    const { projectId, title, description } = requestBody;
                    const task = this.taskService.createTask(projectId, title, description);
                    res.writeHead(201).end(JSON.stringify(task));
                } else if (pathname.startsWith('/tasks/') && method === 'GET') {
                    const id = pathname.split('/')[2];
                    const task = this.taskService.getTask(id);
                    if (task) {
                        res.writeHead(200).end(JSON.stringify(task));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Task not found' }));
                    }
                } else if (pathname.startsWith('/tasks/') && pathname.endsWith('/status') && method === 'PUT') {
                    const taskId = pathname.split('/')[2];
                    const { status } = requestBody;
                    const task = this.taskService.updateTaskStatus(taskId, status);
                    if (task) {
                        res.writeHead(200).end(JSON.stringify(task));
                    } else {
                        res.writeHead(400).end(JSON.stringify({ message: 'Invalid status transition or task not found' }));
                    }
                } else if (pathname.startsWith('/tasks/') && pathname.endsWith('/assign') && method === 'PUT') {
                    const taskId = pathname.split('/')[2];
                    const { assigneeId } = requestBody;
                    const task = this.taskService.assignTask(taskId, assigneeId);
                    if (task) {
                        res.writeHead(200).end(JSON.stringify(task));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Task not found' }));
                    }
                }

                // Comment routes
                else if (pathname === '/comments' && method === 'GET') {
                    const taskId = searchParams.get('taskId');
                    if (taskId) {
                        const comments = this.commentService.getCommentsByTask(taskId);
                        res.writeHead(200).end(JSON.stringify(comments));
                    } else {
                        res.writeHead(400).end(JSON.stringify({ message: 'Missing taskId query parameter' }));
                    }
                } else if (pathname === '/comments' && method === 'POST') {
                    const { taskId, authorId, text } = requestBody;
                    const comment = this.commentService.addComment(taskId, authorId, text);
                    res.writeHead(201).end(JSON.stringify(comment));
                }

                // Notification routes
                else if (pathname === '/notifications' && method === 'GET') {
                    const userId = searchParams.get('userId');
                    if (userId) {
                        const notifications = this.notificationService.getNotificationsForUser(userId);
                        res.writeHead(200).end(JSON.stringify(notifications));
                    } else {
                        res.writeHead(400).end(JSON.stringify({ message: 'Missing userId query parameter' }));
                    }
                } else if (pathname.startsWith('/notifications/') && pathname.endsWith('/read') && method === 'PUT') {
                    const notificationId = pathname.split('/')[2];
                    const notification = this.notificationService.markAsRead(notificationId);
                    if (notification) {
                        res.writeHead(200).end(JSON.stringify(notification));
                    } else {
                        res.writeHead(404).end(JSON.stringify({ message: 'Notification not found' }));
                    }
                }

                // Not found
                else {
                    res.writeHead(404).end(JSON.stringify({ message: 'Not Found' }));
                }
            } catch (error) {
                console.error('Error handling request:', error);
                res.writeHead(500).end(JSON.stringify({ message: 'Internal Server Error' }));
            }
        });
    }
}

import * as http from 'http';
import { ApiRouter } from './api-router';
import { UserService } from './user-service';
import { ProjectService } from './project-service';
import { TaskService } from './task-service';
import { CommentService } from './comment-service';
import { NotificationService } from './notification-service';

// Create service instances
const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService();
const commentService = new CommentService();
const notificationService = new NotificationService(taskService);

// Set up event subscriptions
notificationService.setupSubscriptions();

// Create the API router
const apiRouter = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
);

// Create and start the HTTP server
const server = http.createServer((req, res) => {
    apiRouter.handleRequest(req, res);
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});

import * as http from 'http';

const PORT = 3000;

const makeRequest = (options: http.RequestOptions, data?: any): Promise<any> => {
    return new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
            let body = '';
            res.on('data', (chunk) => (body += chunk));
            res.on('end', () => {
                try {
                    resolve(body ? JSON.parse(body) : {});
                } catch (e) {
                    reject(e)
                }
            });
        });
        req.on('error', (e) => reject(e));
        if (data) {
            req.write(JSON.stringify(data));
        }
        req.end();
    });
};

async function runDemo() {
    try {
        console.log('--- Starting Demo ---');

        // 1. Create users
        console.log('Creating users...');
        const user1 = await makeRequest({ port: PORT, path: '/users', method: 'POST', headers: { 'Content-Type': 'application/json' } }, { name: 'Alice', email: 'alice@example.com' });
        const user2 = await makeRequest({ port: PORT, path: '/users', method: 'POST', headers: { 'Content-Type': 'application/json' } }, { name: 'Bob', email: 'bob@example.com' });
        console.log('Users created:', user1, user2);

        // 2. Create a project
        console.log('Creating a project...');
        const project = await makeRequest({ port: PORT, path: '/projects', method: 'POST', headers: { 'Content-Type': 'application/json' } }, { name: 'My First Project', description: 'A cool project' });
        console.log('Project created:', project);

        // 3. Add members to the project
        console.log('Adding members to the project...');
        await makeRequest({ port: PORT, path: `/projects/${project.id}/members`, method: 'POST', headers: { 'Content-Type': 'application/json' } }, { userId: user1.id });
        await makeRequest({ port: PORT, path: `/projects/${project.id}/members`, method: 'POST', headers: { 'Content-Type': 'application/json' } }, { userId: user2.id });
        console.log('Members added to project.');

        // 4. Create a task
        console.log('Creating a task...');
        const task = await makeRequest({ port: PORT, path: '/tasks', method: 'POST', headers: { 'Content-Type': 'application/json' } }, { projectId: project.id, title: 'Implement feature X', description: 'It should do Y and Z' });
        console.log('Task created:', task);

        // 5. Assign the task to a user
        console.log(`Assigning task ${task.id} to user ${user1.id} ...`);
        await makeRequest({ port: PORT, path: `/tasks/${task.id}/assign`, method: 'PUT', headers: { 'Content-Type': 'application/json' } }, { assigneeId: user1.id });
        console.log('Task assigned.');

        // 6. Check notifications for the assigned user
        console.log(`Checking notifications for user ${user1.id} ...`);
        let notifications = await makeRequest({ port: PORT, path: `/notifications?userId=${user1.id}`, method: 'GET' });
        console.log('Notifications:', notifications);

        // 7. Add a comment to the task
        console.log('Adding a comment to the task...');
        await makeRequest({ port: PORT, path: '/comments', method: 'POST', headers: { 'Content-Type': 'application/json' } }, { taskId: task.id, authorId: user2.id, text: 'Great work!' });
        console.log('Comment added.');

        // 8. Check notifications for the task assignee again
        console.log(`Checking notifications for user ${user1.id} again...`);
        notifications = await makeRequest({ port: PORT, path: `/notifications?userId=${user1.id}`, method: 'GET' });
        console.log('Notifications:', notifications);

        // 9. Change task status
        console.log('Updating task status...');
        await makeRequest({ port: PORT, path: `/tasks/${task.id}/status`, method: 'PUT', headers: { 'Content-Type': 'application/json' } }, { status: 'in-progress' });
        console.log('Task status updated.');

        // 10. Check notifications for the task assignee again
        console.log(`Checking notifications for user ${user1.id} again...`);
        notifications = await makeRequest({ port: PORT, path: `/notifications?userId=${user1.id}`, method: 'GET' });
        console.log('Notifications:', notifications);

        console.log('--- Demo Finished ---');

    } catch (error) {
        console.error('Demo failed:', error);
    } finally {
        // The server will keep running, so we might need to manually stop this script.
        // For a real-world scenario, the server would be started in a separate process.
        process.exit();
    }
}

// We need to wait a bit for the server to start
setTimeout(runDemo, 1000);

